export type AccountPurpose =
  | 'CHECKING'
  | 'PORTFOLIO_CASH'
  | 'PORTFOLIO_RESERVED';

export type AssetCategory =
  | 'CRYPTO'
  | 'ETF'
  | 'STOCK';

export type AssetSort =
  | 'CHANGE_24H'
